import os
import hashlib
import hmac
import unicodedata
import re
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

SECRET_KEY = os.environ.get('APP_SECRET', '')
if not SECRET_KEY:
    raise RuntimeError('APP_SECRET must be set')

DATA_ROOT = os.environ.get('DATA_ROOT', '/var/app/data')


def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)


def generate_api_key(user_id):
    """Generate HMAC-based API key for user."""
    return hmac.new(SECRET_KEY.encode(), user_id.encode(), hashlib.sha256).hexdigest()


def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'unauthorized'}), 401
        token = auth_header[7:]
        # Token format: user_id:hmac_hex
        parts = token.split(':', 1)
        if len(parts) != 2:
            return jsonify({'error': 'invalid token format'}), 401
        user_id, provided_mac = parts
        expected_mac = generate_api_key(user_id)
        if not constant_time_compare(provided_mac, expected_mac):
            return jsonify({'error': 'invalid credentials'}), 401
        g.user_id = user_id
        return f(*args, **kwargs)
    return decorated


def sanitize_document_name(name):
    """Sanitize document name to prevent path traversal.

    Validates that the name contains no path separators or traversal sequences.
    Uses strict allowlist approach.
    """
    # Strip leading/trailing whitespace
    name = name.strip()

    # Check for empty name
    if not name or len(name) > 255:
        return None

    # Block obvious path traversal patterns
    if '..' in name:
        return None
    if '/' in name:
        return None
    if '\\' in name:
        return None
    if name.startswith('.'):
        return None

    # Only allow printable characters
    if not all(c.isprintable() for c in name):
        return None

    # Normalize unicode for consistent storage
    # NFKC normalization ensures equivalent characters are stored uniformly
    normalized = unicodedata.normalize('NFKC', name)

    return normalized


def get_user_document_path(user_id, doc_name):
    """Construct the full path for a user's document."""
    user_dir = os.path.join(DATA_ROOT, 'users', user_id)
    doc_path = os.path.join(user_dir, doc_name)
    return doc_path


@app.route('/api/documents', methods=['POST'])
@require_auth
def create_document():
    """Create a new document for the authenticated user."""
    data = request.get_json()
    if not data or 'name' not in data or 'content' not in data:
        return jsonify({'error': 'name and content required'}), 400

    doc_name = sanitize_document_name(data['name'])
    if doc_name is None:
        return jsonify({'error': 'invalid document name'}), 400

    content = data['content']
    if not isinstance(content, str) or len(content) > 1048576:
        return jsonify({'error': 'content must be string under 1MB'}), 400

    doc_path = get_user_document_path(g.user_id, doc_name)

    # Ensure user directory exists
    os.makedirs(os.path.dirname(doc_path), exist_ok=True)

    with open(doc_path, 'w') as f:
        f.write(content)

    return jsonify({'status': 'created', 'name': doc_name}), 201


@app.route('/api/documents/<doc_name>', methods=['GET'])
@require_auth
def get_document(doc_name):
    """Retrieve a document by name."""
    safe_name = sanitize_document_name(doc_name)
    if safe_name is None:
        return jsonify({'error': 'invalid document name'}), 400

    doc_path = get_user_document_path(g.user_id, safe_name)

    if not os.path.isfile(doc_path):
        return jsonify({'error': 'not found'}), 404

    with open(doc_path, 'r') as f:
        content = f.read()

    return jsonify({'name': safe_name, 'content': content})


@app.route('/api/documents/<doc_name>', methods=['DELETE'])
@require_auth
def delete_document(doc_name):
    """Delete a document by name."""
    safe_name = sanitize_document_name(doc_name)
    if safe_name is None:
        return jsonify({'error': 'invalid document name'}), 400

    doc_path = get_user_document_path(g.user_id, safe_name)

    if not os.path.isfile(doc_path):
        return jsonify({'error': 'not found'}), 404

    os.remove(doc_path)
    return jsonify({'status': 'deleted'})


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
